-- N3-A1 current-lineage fill-facts rollback.
-- Restores the metadata-only preload status snapshot captured before fill.
BEGIN;

DELETE FROM common_market_data_quality_item
WHERE run_id = 'previous_day_minute_preload_20260522_for_20260525__market_data_subscription_20260525_condition_layer_20260522_to_20260525_20260525102249_execute'
  AND gate_code LIKE 'n3_a1_current_fill_%';

DELETE FROM stock_minute_bar_1m
WHERE run_id = 'previous_day_minute_preload_20260522_for_20260525__market_data_subscription_20260525_condition_layer_20260522_to_20260525_20260525102249_execute'
  AND trade_date = '20260522'
  AND is_previous_day_preload = true;

DELETE FROM index_minute_bar_1m
WHERE run_id = 'previous_day_minute_preload_20260522_for_20260525__market_data_subscription_20260525_condition_layer_20260522_to_20260525_20260525102249_execute'
  AND trade_date = '20260522'
  AND is_previous_day_preload = true;

DELETE FROM board_minute_bar_1m
WHERE run_id = 'previous_day_minute_preload_20260522_for_20260525__market_data_subscription_20260525_condition_layer_20260522_to_20260525_20260525102249_execute'
  AND trade_date = '20260522'
  AND is_previous_day_preload = true;

DELETE FROM stock_previous_day_minute_preload_status
WHERE run_id = 'previous_day_minute_preload_20260522_for_20260525__market_data_subscription_20260525_condition_layer_20260522_to_20260525_20260525102249_execute'
  AND trade_date = '20260522';

ON CONFLICT (run_id, trade_date, stock_identity_key, source_adapter)
DO UPDATE SET subscription_id = EXCLUDED.subscription_id, source_condition_run_id = EXCLUDED.source_condition_run_id, for_trade_date = EXCLUDED.for_trade_date, exchange = EXCLUDED.exchange, code = EXCLUDED.code, display_code = EXCLUDED.display_code, name = EXCLUDED.name, expected_bar_count = EXCLUDED.expected_bar_count, actual_bar_count = EXCLUDED.actual_bar_count, missing_bar_count = EXCLUDED.missing_bar_count, first_bar_time = EXCLUDED.first_bar_time, last_bar_time = EXCLUDED.last_bar_time, status = EXCLUDED.status, quality_status = EXCLUDED.quality_status, error_message = EXCLUDED.error_message, source_scope_ids = EXCLUDED.source_scope_ids, source_condition_pool_ids = EXCLUDED.source_condition_pool_ids, raw_json = EXCLUDED.raw_json;

DELETE FROM index_previous_day_minute_preload_status
WHERE run_id = 'previous_day_minute_preload_20260522_for_20260525__market_data_subscription_20260525_condition_layer_20260522_to_20260525_20260525102249_execute'
  AND trade_date = '20260522';

ON CONFLICT (run_id, trade_date, index_identity_key, source_adapter)
DO UPDATE SET subscription_id = EXCLUDED.subscription_id, source_condition_run_id = EXCLUDED.source_condition_run_id, for_trade_date = EXCLUDED.for_trade_date, exchange = EXCLUDED.exchange, code = EXCLUDED.code, display_code = EXCLUDED.display_code, name = EXCLUDED.name, expected_bar_count = EXCLUDED.expected_bar_count, actual_bar_count = EXCLUDED.actual_bar_count, missing_bar_count = EXCLUDED.missing_bar_count, first_bar_time = EXCLUDED.first_bar_time, last_bar_time = EXCLUDED.last_bar_time, status = EXCLUDED.status, quality_status = EXCLUDED.quality_status, error_message = EXCLUDED.error_message, source_scope_ids = EXCLUDED.source_scope_ids, source_condition_pool_ids = EXCLUDED.source_condition_pool_ids, raw_json = EXCLUDED.raw_json;

DELETE FROM board_previous_day_minute_preload_status
WHERE run_id = 'previous_day_minute_preload_20260522_for_20260525__market_data_subscription_20260525_condition_layer_20260522_to_20260525_20260525102249_execute'
  AND trade_date = '20260522';

ON CONFLICT (run_id, trade_date, board_identity_key, source_adapter)
DO UPDATE SET subscription_id = EXCLUDED.subscription_id, source_condition_run_id = EXCLUDED.source_condition_run_id, for_trade_date = EXCLUDED.for_trade_date, exchange = EXCLUDED.exchange, code = EXCLUDED.code, display_code = EXCLUDED.display_code, name = EXCLUDED.name, expected_bar_count = EXCLUDED.expected_bar_count, actual_bar_count = EXCLUDED.actual_bar_count, missing_bar_count = EXCLUDED.missing_bar_count, first_bar_time = EXCLUDED.first_bar_time, last_bar_time = EXCLUDED.last_bar_time, status = EXCLUDED.status, quality_status = EXCLUDED.quality_status, error_message = EXCLUDED.error_message, source_scope_ids = EXCLUDED.source_scope_ids, source_condition_pool_ids = EXCLUDED.source_condition_pool_ids, raw_json = EXCLUDED.raw_json;

UPDATE common_market_data_run
SET status = 'passed',
    p0_count = 0,
    p1_count = 2,
    p2_count = 0,
    market_data_pulled = false,
    market_data_fact_written = false,
    downstream_layers_touched = false,
    worker_started = false,
    finished_at = NULL,
    updated_at = now(),
    raw_json = jsonb_set(
      jsonb_set(COALESCE(raw_json, '{}'::jsonb), '{market_data_pulled}', 'false'::jsonb, true),
      '{market_data_fact_written}', 'false'::jsonb, true
    )
WHERE run_id = 'previous_day_minute_preload_20260522_for_20260525__market_data_subscription_20260525_condition_layer_20260522_to_20260525_20260525102249_execute';

COMMIT;
